{
  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required = payload['required_symbols']
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: set() for n in nodes}
    parent = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children[pid].add(n['id'])
            parent[n['id']] = pid
    retained = set(node_map.keys())
    removal_order = []
    sorted_ids = sorted(node_map.keys(), key=lambda x: (-node_map[x]['depth'], x))
    for nid in sorted_ids:
        if nid not in retained:
            continue
        nd = node_map[nid]
        if not nd['removable']:
            continue
        if children[nid] & retained:
            continue
        current_symbols = {node_map[nid2]['symbol'] for nid2 in retained}
        remaining_symbols = current_symbols - {nd['symbol']}
        if not set(required).issubset(remaining_symbols):
            continue
        retained.remove(nid)
        removal_order.append(nid)
        if nd['parent'] is not None:
            children[nd['parent']].discard(nid)
    retained_sorted = sorted(retained)
    return {'retained': retained_sorted, 'removal_order': removal_order}"
}
